"1252 :     private void ldlTDecomposition(final double lambda, final int index, final int n) {
1253 :         double di = main[index] - lambda;
1254 :         work[0] = Math.abs(di);
1255 :         for (int i = 1; i < n; ++i) {
1256 :             final int    fourI = 4 * i;
1257 :             final double eiM1  = secondary[index + i - 1];
1258 :             final double ratio = eiM1 / di;
1259 :             work[fourI - 2] = ratio * ratio * Math.abs(di);
1260 :             di = (main[index + i] - lambda) - eiM1 * ratio;
1261 :             work[fourI] = Math.abs(di);
1262 :         }
