"755 :     private void process3RowsBlock(final int index)
756 :         throws InvalidMatrixException {
757 : 
758 :         // the characteristic polynomial is
759 :         // X^3 - (q0 + q1 + q2) X^2 + (q0 q1 + q0 q2 + q1 q2 - e1^2 - e2^2) X + q0 e2^2 + q2 e1^2 - q0 q1 q2
760 :         final double q0       = main[index];
761 :         final double q1       = main[index + 1];
762 :         final double q2       = main[index + 2];
763 :         final double e12      = squaredSecondary[index];
764 :         final double q1q2Me22 = q1 * q2 - squaredSecondary[index + 1];
765 : 
766 :         // compute coefficients of the cubic equation as: x^3 + b x^2 + c x + d = 0
767 :         final double b        = -(q0 + q1 + q2);
768 :         final double c        = q0 * q1 + q0 * q2 + q1q2Me22 - e12;
769 :         final double d        = q2 * e12 - q0 * q1q2Me22;
770 : 
771 :         // solve cubic equation
772 :         final double b2       = b * b;
773 :         final double q        = (3 * c - b2) / 9;
774 :         final double r        = ((9 * c - 2 * b2) * b - 27 * d) / 54;
775 :         final double delta    = q * q * q + r * r;
776 :         if (delta >= 0) {
777 :             // in fact, there are solutions to the equation, but in the context
778 :             // of symmetric realEigenvalues problem, there should be three distinct
779 :             // real roots, so we throw an error if this condition is not met
780 :             throw new InvalidMatrixException("cannot solve degree {0} equation", 3);
781 :         }
782 :         final double sqrtMq = Math.sqrt(-q);
783 :         final double theta  = Math.acos(r / (-q * sqrtMq));
784 :         final double alpha  = 2 * sqrtMq;
785 :         final double beta   = b / 3;
786 : 
787 :         double z0 = alpha * Math.cos(theta / 3) - beta;
788 :         double z1 = alpha * Math.cos((theta + 2 * Math.PI) / 3) - beta;
789 :         double z2 = alpha * Math.cos((theta + 4 * Math.PI) / 3) - beta;
790 :         if (z0 < z1) {
791 :             final double t = z0;
792 :             z0 = z1;
793 :             z1 = t;
794 :         }
795 :         if (z1 < z2) {
796 :             final double t = z1;
797 :             z1 = z2;
798 :             z2 = t;
799 :         }
800 :         if (z0 < z1) {
801 :             final double t = z0;
802 :             z0 = z1;
803 :             z1 = t;
804 :         }
805 :         realEigenvalues[index]     = z0;
806 :         realEigenvalues[index + 1] = z1;
807 :         realEigenvalues[index + 2] = z2;
